void WorldRewardCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources,const std::vector<auriga::item::ContainerWorldReward>& expected)
{
    using namespace auriga::item;CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"world reward private SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-world-reward-worker").has_value(),"world reward actual item worker starts");
    for(unsigned n=0;n<sources.size();++n) {
        const auto key=sources[n].grant.key;const ItemOwner owner{ItemOwnerKind::Character,62000u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"world reward owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;std::vector<ContainerWorldReward> spawned;
        const auto op=[&](){return std::array<std::uint8_t,16>{0xAD,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(++serial)};};
        const auto apply=[&](const ItemCommit& commit,std::span<const ContainerWorldReward> world,bool mustWrite=true){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"world reward commit queues");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got && got->state && bool(got->write)==mustWrite,"world reward actual write or CAS refusal observed");replay=got->write && got->write->replay;DispatchContainerWorldRewards(world,got->write.has_value(),replay,[&](const auto& reward){spawned.push_back(reward);});state=*got->state;};
        const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);const auto grant=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,sources[n].grant,ids);if(const auto* rules=catalog->FindDefinitionRules(key);rules && !rules->available){Check(!grant && state.items.empty() && spawned.empty(),"missing original creature assets keep the issued native key unavailable without minting or spawning");continue;}Check(grant.has_value(),"usable original summon can be issued");apply(*grant,{});const auto before=state.items[0];
        const auto output=[&](const char* phase){const auto write=[&](const char* kind,const std::vector<std::byte>& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){auto v=std::to_integer<unsigned>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"world reward actual packet exports");};write("inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());write("details",EncodeTypedItemDetails(*catalog,state.items).value());write("container",EncodeContainerOpening(*catalog,150,&before,nullptr,state.fence.revision,phase==std::string("ready") ? ContainerOpeningStatus::Ready : ContainerOpeningStatus::Opened,{},phase==std::string("ready") ? std::span<const std::uint16_t>{} : std::span<const std::uint16_t>{std::array<std::uint16_t,1>{1}}).value());};
        unsigned draws=0;Check(!MakeContainerOpeningCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,{ids[0],{},{255,0,0,false,false}}, {},[&](auto){++draws;return 0;}) && draws==0 && spawned.empty(),"missing world admission refuses before RNG and any dispatch");output("ready");
        const auto opening=MakeContainerOpeningCommit(*catalog,op(),state.fence,state.storages,state.items,state.wallets,{ids[0],{},{255,0,0,false,true}}, {},[&](auto){++draws;return 0;}).value();Check(opening.worldRewards==std::vector<ContainerWorldReward>{expected[n]} && opening.won==std::vector<std::uint16_t>{1} && draws==1,"actual source row selects its exact creature or group");
        auto refused=opening.commit;refused.operationId=op();refused.owners[0].revision++;const auto saved=state.items;apply(refused,opening.worldRewards,false);Check(spawned.empty() && state.items==saved,"actual failed SQL CAS neither consumes source nor dispatches creatures");
        apply(opening.commit,opening.worldRewards);Check(state.items.empty() && spawned==opening.worldRewards,"actual successful SQL consumption dispatches one exact world reward");output("opened");apply(opening.commit,opening.worldRewards);Check(replay && spawned==opening.worldRewards && state.items.empty(),"actual SQL receipt replay cannot dispatch or consume twice");
        const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(state.items.empty() && spawned==opening.worldRewards,"relog cannot resurrect the source or replay its world result");output("relogged");
    }
    store.Stop();std::cout<<"SOURCE_WORLD_REWARD_WORKER=SUCCESS sources="<<sources.size()<<" checks="<<checks<<std::endl;
}
